// ─── Token Parser ──────────────────────────────────────────
// Liest Tokens aus dem Telegram-Nachrichtentext:
//   g:ja / g:nein  → is_shared
//   p:lena / p:moritz → paid_by
// Rest → note

const message = $input.first().json;
const body = message.message || message.edited_message || {};

// Nutzer-Mapping über Telegram user_id
// WICHTIG: Ersetze diese IDs mit den echten Telegram-User-IDs von Lena und Moritz!
const USER_MAP = {
  123456789: 'lena',    // ← Lenas Telegram-User-ID
  987654321: 'moritz',  // ← Moritz' Telegram-User-ID
};

const userId = body.from?.id;
const owner = USER_MAP[userId] || null;

if (!owner) {
  return [{ json: { error: 'Unbekannter Nutzer', userId, skip: true } }];
}

// Text parsen
const rawText = (body.caption || body.text || '').trim();
const tokens = rawText.split(/\s+/);

let isShared = false;
let paidBy = owner;
const remarkParts = [];

const warnings = [];

for (const token of tokens) {
  const lower = token.toLowerCase();
  if (lower === 'g:ja') {
    isShared = true;
  } else if (lower === 'g:nein') {
    isShared = false;
  } else if (lower === 'p:lena') {
    paidBy = 'lena';
  } else if (lower === 'p:moritz') {
    paidBy = 'moritz';
  } else if (lower.startsWith('g:') || lower.startsWith('p:')) {
    // Unbekannter Token
    warnings.push(`Unbekanntes Token: ${token}`);
    remarkParts.push(token);
  } else {
    remarkParts.push(token);
  }
}

const note = remarkParts.join(' ').trim() || null;

// Datei-Infos
const photo = body.photo || null;
const document = body.document || null;
const hasFile = !!(photo || document);

let fileId = null;
let fileType = null;

if (photo && photo.length > 0) {
  // Größtes Foto nehmen
  fileId = photo[photo.length - 1].file_id;
  fileType = 'photo';
} else if (document) {
  fileId = document.file_id;
  fileType = document.mime_type === 'application/pdf' ? 'pdf' : 'document';
}

return [{
  json: {
    owner,
    isShared,
    paidBy,
    note,
    fileId,
    fileType,
    hasFile,
    warnings,
    chatId: body.chat?.id,
    messageId: body.message_id,
    userId,
    rawText,
  }
}];

// Datei als Base64 kodieren für Claude API
const binaryData = $input.first().binary;
const parsed = $('Tokens parsen').first().json;
const fileInfo = $('Datei-Pfad holen').first().json;

const fileKey = Object.keys(binaryData)[0];
const file = binaryData[fileKey];

// Base64 Daten
const base64Data = Buffer.from(await $helpers.getBinaryDataBuffer(binaryData, fileKey)).toString('base64');

// Medientyp bestimmen
let mediaType = 'image/jpeg';
if (parsed.fileType === 'pdf') {
  mediaType = 'application/pdf';
} else if (file.mimeType) {
  mediaType = file.mimeType;
}

// Dateiname für Storage
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const ext = parsed.fileType === 'pdf' ? 'pdf' : 'jpg';
const fileName = `${parsed.owner}/${timestamp}.${ext}`;

return [{
  json: {
    ...parsed,
    base64Data,
    mediaType,
    fileName,
  }
}];

// Wenn kein Dateianhang: Minimal-Datensatz erstellen
const parsed = $input.first().json;
return [{
  json: {
    ...parsed,
    base64Data: null,
    mediaType: null,
    fileName: null,
  }
}];

