// KI-Antwort parsen und mit Telegram-Daten zusammenführen
const aiResponse = $input.first().json;
const tokenData = $('Tokens parsen').first().json;

let extracted = {};
try {
  const content = aiResponse.content?.[0]?.text || '{}';
  // JSON aus Antwort extrahieren (falls Markdown-Blöcke)
  const cleaned = content.replace(/```json|```/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = {
    date: null,
    merchant: null,
    total_amount: null,
    category: 'Andere',
    confidence: 'low',
  };
}

// Validierung: Betrag muss positiv sein
if (extracted.total_amount && extracted.total_amount < 0) {
  extracted.total_amount = Math.abs(extracted.total_amount);
}

// Kategorie-Fallback
const validCategories = [
  'Lebensmittel', 'Restaurant & Café', 'Haushalt & Wohnen',
  'Gesundheit & Apotheke', 'Kleidung & Mode', 'Elektronik & Technik',
  'Transport & Auto', 'Freizeit & Sport', 'Reisen & Urlaub',
  'Bildung & Bücher', 'Beauty & Pflege', 'Versicherung & Finanzen',
  'Sonstiges', 'Andere'
];
if (!validCategories.includes(extracted.category)) {
  extracted.category = 'Andere';
}

return [{
  json: {
    // Ownership
    owner: tokenData.owner,
    is_shared: tokenData.isShared,
    paid_by: tokenData.paidBy,

    // Extrahiert
    receipt_date: extracted.date || null,
    merchant: extracted.merchant || null,
    total_amount: extracted.total_amount || null,
    category: extracted.category || 'Andere',

    // MwSt
    vat_7_base: extracted.vat_7_base || null,
    vat_7_amount: extracted.vat_7_amount || null,
    vat_19_base: extracted.vat_19_base || null,
    vat_19_amount: extracted.vat_19_amount || null,

    // Metadaten
    note: tokenData.note,
    telegram_message_id: tokenData.messageId,
    telegram_user_id: tokenData.userId,
    file_path: null, // wird in nächstem Schritt gesetzt
    extraction_confidence: extracted.confidence || 'medium',

    // Für spätere Schritte
    _chatId: tokenData.chatId,
    _warnings: tokenData.warnings || [],
    _hasFile: tokenData.hasFile,
    _base64Data: tokenData.base64Data,
    _mediaType: tokenData.mediaType,
    _fileName: tokenData.fileName,
  }
}];

// Bestätigungsnachricht zusammenstellen
const data = $input.first().json;
const saved = Array.isArray(data) ? data[0] : data;

// Felder aus dem Input (falls Save Response leer)
const src = saved.owner ? saved : $('KI-Antwort verarbeiten').first().json;

const formatEuro = (v) => v != null ? v.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }) : '—';
const formatDate = (d) => d ? new Date(d).toLocaleDateString('de-DE') : '—';
const capitalize = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;

const bereich = src.is_shared ? '👫 Gemeinsam' : '🔒 Privat';
const paidBy = capitalize(src.paid_by);

let msg = `✅ *Beleg gespeichert*\n\n`;
msg += `📍 Bereich: ${bereich}\n`;
msg += `🏪 Händler: ${src.merchant || '—'}\n`;
msg += `💶 Betrag: ${formatEuro(src.total_amount)}\n`;
msg += `📅 Datum: ${formatDate(src.receipt_date)}\n`;
msg += `🏷 Kategorie: ${src.category}`;

if (src.category === 'Andere') {
  msg += ' _(Kategorie nicht erkannt)_';
}

msg += `\n👤 Ausleger: ${paidBy}\n`;

if (src.note) {
  msg += `📝 Notiz: ${src.note}\n`;
}

if (src.extraction_confidence === 'low') {
  msg += `\n⚠️ _Niedrige Erkennungsqualität — bitte in der App prüfen._\n`;
}

if (src._warnings && src._warnings.length > 0) {
  msg += `\n⚠️ _Hinweis: ${src._warnings.join(', ')}_\n`;
}

msg += `\n💡 _In der App bearbeitbar: https://belege.staebler.dev/_`;

return [{
  json: {
    chatId: src._chatId,
    text: msg,
  }
}];

// Fehlerbehandlung: Fehlermeldung an Nutzer
const errData = $input.first().json;
console.error('BelegBot Fehler:', JSON.stringify(errData));

const parsed = $('Tokens parsen').first().json;
return [{
  json: {
    chatId: parsed.chatId,
    text: '❌ Fehler beim Speichern des Belegs. Bitte versuche es erneut oder wende dich an den Administrator.',
  }
}];
